    <section class="chrome-cms-section" data-panel="footer_content"><h2>Footer Content</h2><div class="combo-form-grid"><label>Footer logo<input class="fi" name="footer_logo" required><span class="chrome-one-click"><input type="file" data-logo="footer_logo" accept="image/png,image/jpeg,image/webp">Select a new logo to upload instantly</span></label><label>Footer description<textarea class="fi" name="footer_description" rows="5"></textarea></label></div></section>
