<script>
const CHROME_CSRF='<?= htmlspecialchars($csrf??'',ENT_QUOTES) ?>',locations={header:'Main Menu',footer_quick:'Quick Links',footer_products:'Products',footer_service:'Customer Service'};let chromeData={settings:{},navigation:{}};
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
function navRow(x={},key=''){return `<div class="chrome-nav-row"><span class="chrome-drag" title="Use arrows to reorder">⋮⋮</span><input class="fi" data-field="label" value="${esc(x.label)}" placeholder="Menu text"><input class="fi" data-field="url" value="${esc(x.url)}" placeholder="/page-link"><label class="chrome-nav-active"><input type="checkbox" data-field="is_active" ${Number(x.is_active??1)?'checked':''}> Active</label><span class="chrome-order-actions"><button type="button" onclick="moveNav(this,-1)" aria-label="Move up">↑</button><button type="button" onclick="moveNav(this,1)" aria-label="Move down">↓</button></span><button type="button" class="btn btn-outline btn-sm" onclick="removeNav(this)">Remove</button></div>`;}
function renderEditors(){document.querySelector('[data-nav="header"]').innerHTML=(chromeData.navigation.header||[]).map(x=>navRow(x,'header')).join('');document.getElementById('footerMenuEditors').innerHTML=Object.entries(locations).filter(([key])=>key!=='header').map(([key,title])=>`<section class="chrome-nav-editor"><div class="combo-admin-head"><h3>${title}</h3><button type="button" class="btn btn-outline btn-sm" onclick="addNav('${key}')">+ Add Link</button></div><div data-nav="${key}">${(chromeData.navigation[key]||[]).map(x=>navRow(x,key)).join('')}</div></section>`).join('');}
function addNav(key){document.querySelector(`[data-nav="${key}"]`).insertAdjacentHTML('beforeend',navRow({},key));}
async function removeNav(button){if(await adminConfirm('Remove this menu item?'))button.closest('.chrome-nav-row').remove();}
function moveNav(button,direction){const row=button.closest('.chrome-nav-row'),sibling=direction<0?row.previousElementSibling:row.nextElementSibling;if(!sibling)return;direction<0?row.parentElement.insertBefore(row,sibling):row.parentElement.insertBefore(sibling,row);}
async function uploadLogo(key,file){if(!file)return;const state=document.getElementById('chromeSaveState');state.textContent='Uploading image…';const fd=new FormData();fd.append('image',file);const r=await fetch('/admin/api/site-chrome/logo',{method:'POST',headers:{'X-CSRF-TOKEN':CHROME_CSRF},body:fd}).then(x=>x.json()).catch(()=>({ok:false,msg:'Upload failed'}));if(r.ok){document.getElementById('chromeForm').elements[key].value=r.path;state.textContent='Image uploaded. Save changes to publish it.';}else state.textContent=r.msg||'Upload failed.';}
async function loadChrome(){const r=await fetch('/admin/api/site-chrome',{cache:'no-store'}).then(x=>x.json());if(!r.ok)return;chromeData=r.data;const f=document.getElementById('chromeForm');for(const[k,v]of Object.entries(chromeData.settings)){if(!f.elements[k])continue;if(f.elements[k].type==='checkbox')f.elements[k].checked=Number(v)===1;else f.elements[k].value=v||'';}renderEditors();}
function collect(){const f=document.getElementById('chromeForm'),settings={};for(const field of f.querySelectorAll('[name]'))settings[field.name]=field.type==='checkbox'?(field.checked?1:0):field.value;const navigation={};for(const key of Object.keys(locations))navigation[key]=[...document.querySelectorAll(`[data-nav="${key}"] .chrome-nav-row`)].map(row=>({label:row.querySelector('[data-field="label"]').value.trim(),url:row.querySelector('[data-field="url"]').value.trim(),is_active:row.querySelector('[data-field="is_active"]').checked?1:0}));return{settings,navigation};}
async function saveChrome(){const button=document.getElementById('saveChrome'),state=document.getElementById('chromeSaveState');button.disabled=true;state.textContent='Saving…';const r=await fetch('/admin/api/site-chrome',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':CHROME_CSRF},body:JSON.stringify(collect())}).then(x=>x.json()).catch(()=>({ok:false,msg:'Save failed'}));button.disabled=false;state.textContent=r.ok?'Header and footer published successfully.':(r.msg||'Save failed.');}
document.querySelectorAll('.chrome-cms-nav button').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.chrome-cms-nav button,.chrome-cms-section').forEach(el=>el.classList.remove('is-active'));button.classList.add('is-active');document.querySelector(`[data-panel="${button.dataset.section}"]`).classList.add('is-active');}));
document.querySelectorAll('[data-logo]').forEach(input=>input.addEventListener('change',()=>uploadLogo(input.dataset.logo,input.files[0])));document.getElementById('saveChrome').addEventListener('click',saveChrome);loadChrome();
</script></div></div></div></body></html>
